			} else if (starts_with(nodename, "entrance_")) {
				m_model->AddTag(nodename, parent, new Tag(m_renderer, m));
			} else if (starts_with(nodename, "loc_")) {
				m_model->AddTag(nodename, parent, new Tag(m_renderer, m));
